const state = $getWorkflowStaticData('global');
if (!state.issues) state.issues = {};
const firstRun = !state.seeded;
const now = Date.now();
const esc = function (s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const base = 'https://futuremedia.atlassian.net/browse/';
const issues = ($input.first().json.issues) || [];
const out = [];
for (const it of issues) {
  const f = it.fields || {};
  const llrs = (f.issuelinks || []).filter(function (l) { return l.type && l.type.id === '10079' && l.outwardIssue; }).map(function (l) { return l.outwardIssue; });
  if (!llrs.length) continue;
  const status = f.status ? f.status.name : '';
  const versions = (f.fixVersions || []).map(function (v) { return { name: v.name, releaseDate: v.releaseDate || '', released: !!v.released }; });
  const sigOf = function (v) { return v.name + '|' + v.releaseDate + '|' + v.released; };
  const verSig = versions.map(sigOf).sort().join(';');
  const prev = state.issues[it.key];
  state.issues[it.key] = { status: status, verSig: verSig, seen: now, threadTs: prev && prev.threadTs ? prev.threadTs : '' };
  if (firstRun || !prev) continue;
  const changes = [];
  if (prev.status !== status) {
    const prodNote = status === 'QA PROD' ? ' :rocket: _deployed to prod_' : '';
    changes.push('Status: ' + esc(prev.status) + ' → *' + esc(status) + '*' + prodNote);
  }
  if (prev.verSig !== verSig) {
    const prevSigs = prev.verSig ? prev.verSig.split(';') : [];
    for (const v of versions) {
      const p = prevSigs.find(function (s) { return s.indexOf(v.name + '|') === 0; });
      if (!p) changes.push('Fix version added: *' + esc(v.name) + '*' + (v.releaseDate ? ' (planned release ' + v.releaseDate + ')' : ''));
      else if (v.released && p.slice(-5) !== '|true') changes.push(':rocket: Version *' + esc(v.name) + '* *released*' + (v.releaseDate ? ' on *' + v.releaseDate + '*' : ''));
      else if (p !== sigOf(v)) changes.push('Fix version *' + esc(v.name) + '* updated (release date ' + (v.releaseDate || 'not set') + ')');
    }
  }
  if (!changes.length) continue;
  const verLine = versions.length ? versions.map(function (v) { return esc(v.name) + ' (' + (v.releaseDate || 'no date') + (v.released ? ', released' : ', not released') + ')'; }).join(', ') : 'none';
  const llrLine = llrs.map(function (l) { const st = l.fields && l.fields.status ? l.fields.status.name : ''; return '<' + base + l.key + '|' + l.key + '>' + (st ? ' (' + esc(st) + ')' : ''); }).join(', ');
  const text = ':bell: *<' + base + it.key + '|' + it.key + '>* – ' + esc(f.summary) + '\n' + changes.join('\n') + '\nFix version: ' + verLine + '\nLocalization ticket: ' + llrLine;
  out.push({ json: { key: it.key, status: status, llrKeys: llrs.map(function (l) { return l.key; }), threadTs: state.issues[it.key].threadTs, changesText: changes.join('\n'), text: text } });
}
for (const k of Object.keys(state.issues)) { if (now - (state.issues[k].seen || 0) > 90 * 86400000) delete state.issues[k]; }
state.seeded = true;
return out;

